```typescript
class Ticket implements Comparable<Ticket> {
  id: number;
  title: string;
  description: string;
  priority: string;
  deadline: string;

  constructor(id: number, title: string, description: string, priority: string, deadline: string) {
    this.id = id;
    this.title = title;
    this.description = description;
    this.priority = priority;
    this.deadline = deadline;
  }

  public compareTo(other: Ticket): number {
    // Implementiere die Sortierung nach Priorität
    return this.priority.localeCompare(other.priority);
  }
}
```

